const S = $('Settings').first().json;
const res = [];
for (let r = 0; r < 500; r++) {
  let its;
  try { its = $('Row Payload').all(0, r); } catch (e) { break; }
  if (!its || !its.length) break;
  res.push(...its.map(i => i.json));
